    });
  }

  const x = normalizeOptionalNumber(cameraData.x, DEFAULT_CAMERA.x, "camera.x");
  if (!x.ok) return x;

  const y = normalizeOptionalNumber(cameraData.y, DEFAULT_CAMERA.y, "camera.y");
  if (!y.ok) return y;

  const zoom = normalizeOptionalNumber(
    cameraData.zoom,
    DEFAULT_CAMERA.zoom,
    "camera.zoom"
  );
  if (!zoom.ok) return zoom;

  return {
