import { describe, expect, it, vi } from "vitest";
import { useDrawfn, type UseDrawfnResult } from "../use-drawfn";

function createScene(): Scene {
  return {
    version: 1,
    id: "scene-1",
    camera: { x: 0, y: 0, zoom: 1 },
    background: { color: "#ffffff" },
    elements: [
      {
        id: "rect-1",
        type: "rectangle",
        x: 10,
        y: 20,
        w: 80,
        h: 40,
        rotation: 0,
        stroke: "#000000",
        fill: "transparent",
        strokeWidth: 2,
        opacity: 1,
      },
    ],
  };
}

function rectangle(id: string) {
  return {
    id,
    type: "rectangle" as const,
    x: 10,
    y: 20,
    w: 80,
    h: 40,
    rotation: 0,
    stroke: "#000000",
    fill: "transparent" as const,
    strokeWidth: 2,
    opacity: 1,
  };
}

function HookHarness(props: {
  scene?: Scene;
  onSceneChange?: (scene: Scene, meta?: any) => void;
  onReady?: (value: UseDrawfnResult) => void;
}) {
  const drawfn = useDrawfn({
    scene: props.scene,
    onSceneChange: props.onSceneChange,
  });

  React.useEffect(() => {
    if (drawfn.isReady && props.onReady) {
      props.onReady(drawfn);
    }
  }, [drawfn.drawfn, drawfn.isReady, props.onReady]);

  return <canvas ref={drawfn.canvasRef} width={800} height={600} />;
}

describe("useDrawfn", () => {
  it("suppresses deep-equal controlled scene echoes without reloading", async () => {
    const loadSpy = vi.spyOn(Drawfn.prototype, "load");
    let readyApi: UseDrawfnResult | null = null;

    function ControlledHarness() {
      const [scene, setScene] = React.useState<Scene>(createScene());
      return (
        <HookHarness
          scene={scene}
          onReady={(value) => {
            readyApi = value;
          }}
          onSceneChange={(nextScene) => {
            setScene(nextScene);
          }}
        />
      );
    }

    render(<ControlledHarness />);

    await waitFor(() => {
      expect(readyApi?.drawfn).toBeTruthy();
    });
    expect(loadSpy).toHaveBeenCalledTimes(1);

    act(() => {
      readyApi?.drawfn?.clear();
    });

    await waitFor(() => {
      expect(readyApi?.drawfn?.getScene().elements).toHaveLength(0);
    });
    expect(loadSpy).toHaveBeenCalledTimes(1);
    loadSpy.mockRestore();
  });

  it("propagates camera, undo, and redo through onSceneChange meta from sceneChanged", async () => {
    let readyApi: UseDrawfnResult | null = null;
    const reasons: Array<string | undefined> = [];

    render(
      <HookHarness
        onReady={(value) => {
          readyApi = value;
        }}
        onSceneChange={(_scene, meta) => {
          reasons.push(meta?.reason);
        }}
      />
    );

    await waitFor(() => {
      expect(readyApi?.drawfn).toBeTruthy();
    });

    act(() => {
      readyApi?.drawfn?.add(rectangle("rect-2"));
      readyApi?.drawfn?.setCamera({ x: 120 });
      readyApi?.drawfn?.undo();
      readyApi?.drawfn?.redo();
    });

    await waitFor(() => {
      expect(reasons).toContain("camera");
      expect(reasons).toContain("undo");
      expect(reasons).toContain("redo");
    });
  });
});
<script lang="ts">
  export let width = 800;
  export let height = 600;

  let className = "";
  export { className as class };
</script>

<canvas
  {width}
  {height}
  class={className}
  style={`display: block; touch-action: none; ${$$restProps.style ?? ""}`}
  {...$$restProps}
/>
<script lang="ts">
  import { onMount } from "svelte";
  import {
    Drawfn,
    type DrawfnOptions,
    type Scene,
    type SceneChangedEvent,
    type ToolName,
  } from "drawfn";

  export let width = 800;
  export let height = 600;
  export let scene: Scene | undefined = undefined;
  export let overlayRoot: HTMLElement | undefined = undefined;
  export let getImageBitmap: DrawfnOptions['getImageBitmap'] = undefined;
  export let onReady: ((drawfn: Drawfn) => void) | undefined = undefined;
  export let onSceneChange:
    | ((scene: Scene, meta?: SceneChangedEvent) => void)
    | undefined = undefined;

  let canvas: HTMLCanvasElement | null = null;
  let drawfn: Drawfn | null = null;
  let lastLoadedSceneKey: string | null = null;
  let unsubscribeSceneChanged: (() => void) | undefined = undefined;
  let className = "";
  export { className as class };

  function scenesAreEqual(left?: Scene, right?: Scene): boolean {
    if (!left || !right) {
      return left === right;
    }

    return JSON.stringify(left) === JSON.stringify(right);
  }

  function serializeScene(value?: Scene): string | null {
    return value ? JSON.stringify(value) : null;
  }

  onMount(() => {
    if (!canvas) return;

    const instance = new Drawfn({
      canvas,
      overlayRoot,
      getImageBitmap,
    });
    drawfn = instance;

    unsubscribeSceneChanged = instance.on("sceneChanged", (meta) => {
      onSceneChange?.(meta.scene, meta);
    }) ?? undefined;

    const sceneKey = serializeScene(scene);
    if (scene && !scenesAreEqual(instance.getScene(), scene)) {
      lastLoadedSceneKey = sceneKey;
      instance.load(scene);
    }

    onReady?.(instance);

    return () => {
      unsubscribeSceneChanged?.();
      instance.destroy();
      unsubscribeSceneChanged = undefined;
      lastLoadedSceneKey = null;
      drawfn = null;
    };
  });

  $: if (drawfn && scene) {
    const sceneKey = serializeScene(scene);
    if (
      sceneKey !== lastLoadedSceneKey &&
      !scenesAreEqual(drawfn.getScene(), scene)
    ) {
      lastLoadedSceneKey = sceneKey;
      drawfn.load(scene);
    } else {
      lastLoadedSceneKey = sceneKey;
    }
  }

  // Expose drawfn instance
  export function getDrawfn(): Drawfn | null {
    return drawfn;
  }

  export function setTool(tool: ToolName, opts?: any): void {
    drawfn?.setTool(tool, opts);
  }

  export function undo(): void {
    drawfn?.undo();
  }

  export function redo(): void {
    drawfn?.redo();
  }

  export function clear(): void {
    drawfn?.clear();
  }

  export async function exportPNG(opts?: Parameters<Drawfn['exportPNG']>[0]): Promise<Blob | undefined> {
    return await drawfn?.exportPNG(opts);
  }

  export async function exportSVG(opts?: Parameters<Drawfn['exportSVG']>[0]): Promise<string | undefined> {
    return await drawfn?.exportSVG(opts);
  }
</script>

<canvas
  bind:this={canvas}
  {width}
  {height}
  class={className}
  style={`display: block; touch-action: none; ${$$restProps.style ?? ""}`}
  {...$$restProps}
/>
"}

