 */
function requirementIdsForControl(framework: Framework, controlId: string): string[] {
  const ids: string[] = [];
  for (const req of framework.requirements) {
    if (req.controlIds.includes(controlId)) {
      ids.push(req.requirementId);
    }
  }
  return ids;
