      checksToRun = listResult.result.map((check) => check.id);
    }

    if (checksToRun.length === 0) {
      console.log("No checks to run.");
      process.exit(0);
    }

    let passCount = 0;
    let failCount = 0;
    let unknownCount = 0;

    for (const checkId of checksToRun) {
