      type: "rectangle",
      x: this.startPoint.x,
      y: this.startPoint.y,
      w: 0,
      h: 0,
      rotation: 0,
      stroke: "#000000",
      fill: "transparent",
      strokeWidth: 2,
      opacity: 1,
    };

    this.currentElementId = context.addElement(element);
  }

  handlePointerMove(e: PointerEvent, context: ToolContext): void {
    if (!this.startPoint || !this.currentElementId) return;

    const canvas = e.target as HTMLCanvasElement;
