export function canvasToScreen(
  canvasPoint: Point,
  camera: Camera
): Point {
  return {
    x: canvasPoint.x * camera.zoom + camera.x,
    y: canvasPoint.y * camera.zoom + camera.y,
  };
}

export function getElementBounds(element: Element): Bounds {
  return {
    x: element.x,
    y: element.y,
    w: element.w,
    h: element.h,
