            } else if (options.every) {
                task.nextRun = Date.now() + options.every;
            }
            this.plan(name);
        }
    }

    async close(): Promise<void> {
        for (const task of this.tasks.values()) {
            if (task.timer) clearTimeout(task.timer);
        }
